package com.onrender.smartnf.health;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;
public class ProductFlowTests {
 static int checks;static void ok(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}static void fails(Runnable fn){try{fn.run();throw new AssertionError("expected failure");}catch(HealthException expected){checks++;}}
 static ShoppingProductService.Save body(UUID list,long lr,long expected,UUID req,int packs){return new ShoppingProductService.Save(list,0,lr,expected,req,"123","양파 1kg","판매자",new BigDecimal("1000"),new BigDecimal("3000"),packs,"https://www.11st.co.kr/products/123","2026-11-13T07:00:00Z",true);}
 public static void main(String[] args)throws Exception{
  String xml="<ProductSearchResponse><Products><Product><ProductCode>123</ProductCode><ProductName>양파 1kg</ProductName><Seller>농장</Seller><ProductPrice>3000</ProductPrice><SalePrice>100</SalePrice><Delivery>무료</Delivery></Product><Product><ProductCode>bad</ProductCode><ProductPrice>1</ProductPrice></Product></Products></ProductSearchResponse>";
  var result=IngredientProductService.parse(xml.getBytes(StandardCharsets.UTF_8),"now");ok(result.products().size()==1,"valid rows only");ok(result.products().getFirst().grams().intValue()==1000,"weight");ok(result.products().getFirst().price().intValue()==3000,"no conditional sale substitution");ok(IngredientProductService.weight("양파 1kg x 2팩")==null,"multipack ambiguous");ok(IngredientProductService.weight("양파 500g 1kg 선택")==null,"options ambiguous");ok(IngredientProductService.weight("양파 1개")==null,"no guessed weight");ok(IngredientProductService.weight("양파 500g").intValue()==500,"single explicit weight");
  try{IngredientProductService.parse("<!DOCTYPE a [<!ENTITY x SYSTEM 'file:///missing'>]><ProductSearchResponse>&x;</ProductSearchResponse>".getBytes(),"now");throw new AssertionError("XXE allowed");}catch(org.xml.sax.SAXException expected){checks++;}
  var ds=new DriverManagerDataSource("jdbc:h2:mem:product;MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");var jdbc=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));jdbc.execute("CREATE TABLE members(id BIGINT PRIMARY KEY)");jdbc.update("INSERT INTO members(id) VALUES(1),(2)");for(String file:args)for(String sql:Files.readString(Path.of(file)).split(";"))if(!sql.isBlank())jdbc.execute(sql);
  var lists=new ShoppingListService(jdbc);var products=new ShoppingProductService(jdbc,lists);UUID id=UUID.randomUUID();var plan=new ShoppingListModels.Save(id,UUID.randomUUID(),0L,LocalDate.of(2026,11,25),LocalDate.of(2027,4,25),LocalDate.of(2027,4,30),"WEEK",List.of(new ShoppingListModels.Item("onion","양파",new BigDecimal("700"))));tx.execute(s->lists.save(1,plan));
  var current=new CurrentHealthMember();var controller=new IngredientProductController(current,new IngredientProductService(){@Override public Result search(String q){return new Result("11ST",List.of(),"test");}},new CollectedProductService(jdbc));fails(()->controller.search(null,"양파"));var auth=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(new com.onrender.smartnf.member.MemberPrincipal(new com.onrender.smartnf.member.MemberRepository.LoginMember(1,"test@example.com","hash","test","ACTIVE"),List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_USER"))),"",List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_USER")));ok("no-store".equals(controller.search(auth,"양파").getHeaders().getFirst("Cache-Control")),"authenticated controller no-store");var unknown=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken("unknown","",List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_USER")));fails(()->controller.search(unknown,"양파"));var choiceController=new ShoppingProductController(current,products);fails(()->choiceController.get(null,id));ok(choiceController.get(auth,id).getBody().isEmpty(),"authenticated choice controller");
  var save=body(id,1,0,UUID.randomUUID(),2);var selected=tx.execute(s->products.save(1,save));ok(selected.revision()==1&&selected.packs()==2,"save selection");ok(lists.get(1,id).items().getFirst().grams().intValue()==700,"required quantity unchanged");ok(products.get(1,id).getFirst().packGrams().intValue()==1000,"read choice");ok(tx.execute(s->products.save(1,save)).revision()==1,"idempotent retry");fails(()->tx.execute(s->products.save(1,body(id,1,0,save.requestId(),3))));fails(()->products.get(2,id));fails(()->tx.execute(s->products.save(2,save)));fails(()->tx.execute(s->products.save(1,body(id,1,0,UUID.randomUUID(),3))));
  tx.execute(s->products.save(1,body(id,1,1,UUID.randomUUID(),3)));ok(products.get(1,id).getFirst().packs()==3,"update quantity");
  var edit=new ShoppingListModels.Save(id,UUID.randomUUID(),1L,plan.shoppingDate(),plan.sourceFrom(),plan.sourceTo(),"WEEK",List.of(new ShoppingListModels.Item("onion","양파",new BigDecimal("900"))));tx.execute(s->lists.save(1,edit));ok(products.get(1,id).getFirst().stale(),"list edit marks previous choice stale");fails(()->tx.execute(s->products.save(1,body(id,1,2,UUID.randomUUID(),4))));
  try{tx.execute(s->{products.save(1,body(id,2,2,UUID.randomUUID(),4));throw new IllegalStateException("rollback");});}catch(IllegalStateException expected){}ok(products.get(1,id).getFirst().packs()==3,"rollback");jdbc.update("DELETE FROM members WHERE id=1");ok(jdbc.queryForObject("SELECT COUNT(*) FROM shopping_product_choices",Integer.class)==0,"account delete cascade");
  System.out.println("PASS "+checks+" product parsing, selection, isolation, revision and transaction checks");
 }
}
